#pragma once

// Native <-> recompiled code bridging. Native code (libil2cpp, UnityPlayer)
// calls game code through entry thunks generated by tools/recomp/gen_bridges.py;
// each thunk builds a Ctx with the arm64 register assignment of its arguments,
// runs the recompiled function on this thread's guest stack and converts the
// result back.

#include <cstddef>
#include <cstdint>
#include <cstring>

#include "recomp_ctx.h"

namespace recomp
{
    // Opaque by-value struct with the size and alignment of a game value type.
    // Windows x64 only needs those two properties to pass or return it.
    template <size_t Size, size_t Align>
    struct alignas(Align) Blob
    {
        uint8_t bytes[Size];
    };

    // Guest stack of the current thread. Entry thunks start below the stack
    // pointer that was current when guest code last called into native code,
    // so nested native -> guest -> native -> guest calls never overlap.
    struct GuestStackScope
    {
        uint64_t saved;
        GuestStackScope();
        ~GuestStackScope();
        uint64_t Top() const;
    };

    // Called by bridges when guest code calls native code, so that native
    // code calling back into the guest continues below the caller's frame.
    void SetGuestStackPointer(uint64_t sp);

    struct BridgeEntry
    {
        uint64_t slot;        // guest address of the table slot to patch
        void* thunk;          // native-callable entry point
        Function function;    // recompiled function it runs
    };

    // Rewrites the registration tables in the loaded image to point at the
    // entry thunks, and records thunk -> function for CallIndirect.
    void InstallBridges();
    Function FunctionForThunk(uint64_t hostAddress);

    // Argument packing helpers used by the generated thunks.
    inline uint64_t ExtendSigned(int64_t v) { return uint64_t(v); }
    inline uint64_t ExtendUnsigned(uint64_t v) { return v; }

    template <typename T>
    inline void CopyToRegs(uint64_t* regs, const T& value)
    {
        uint64_t tmp[2] = {};
        memcpy(tmp, &value, sizeof(T));
        regs[0] = tmp[0];
        if (sizeof(T) > 8)
            regs[1] = tmp[1];
    }

    template <typename T>
    inline T CopyFromRegs(const uint64_t* regs)
    {
        uint64_t tmp[2] = { regs[0], sizeof(T) > 8 ? regs[1] : 0 };
        T value;
        memcpy(&value, tmp, sizeof(T));
        return value;
    }
}
